<div class="page-heading"><div><p class="eyebrow">EVERY CUP HAS A STORY</p><h1>A little record of good things.</h1><p>Every sale, its customer, and the person behind the counter.</p></div><a class="button dark" href="<?= site_url('pos') ?>">+ Record sale</a></div><section class="table-panel"><div class="table-toolbar"><div><h2>Sales history <span class="count-pill"><?= count($sales) ?></span></h2><p>Newest first · Totals retain the price at the time of sale</p></div><label class="search"><span>⌕</span><input type="search" data-table-search placeholder="Search sales…" aria-label="Search sales"></label></div><div class="table-scroll"><table><thead><tr><th>RECEIPT</th><th>PRODUCT</th><th>CUSTOMER</th><th>SOLD BY</th><th>QTY</th><th>TOTAL</th><th>DATE</th></tr></thead><tbody><?php foreach($sales as $sale): ?><tr data-search-row><td><a class="text-link" href="<?= site_url('sales/'.$sale['id']) ?>">#<?= str_pad($sale['id'],4,'0',STR_PAD_LEFT) ?> ↗</a></td><td><?= esc($sale['product_name']) ?></td><td><?= esc($sale['customer_name']??'Walk-in guest') ?></td><td><?= esc($sale['staff_name']) ?></td><td><?= (int)$sale['quantity'] ?></td><td><?= peso($sale['total_price']) ?></td><td><?= esc(date('d M Y, h:i A',strtotime($sale['created_at']))) ?></td></tr><?php endforeach ?></tbody></table></div><p class="empty-search" data-search-empty <?= $sales?'hidden':'' ?>><?= $sales?'No matching sales.':'No sales yet. Your first cup is waiting.' ?></p></section>
